import React, { HTMLAttributes } from 'react';

import clsx from 'clsx';

import { getEquipItems, IGetEquipCriteria } from '@apps/Hiking/@services/equip.service';
import { IEquip } from '@apps/Hiking/@types/equip.types';
import PageLoader from '@components/PageLoader';
import PohAlert, { AlertVariant } from '@ui-kit/Alert';
import Empty from '@ui-kit/Empty';
import PohInput, { InputTypes } from '@ui-kit/Input';
import PohList from '@ui-kit/List';

import EquipListItem from '../EquipListItem';

interface IEquipListProps {
  criteria?: IGetEquipCriteria;
  showEmptyMessage?: boolean;
  header?: React.ReactNode;
  onSelectEquipItem?: (equip: IEquip, e: React.MouseEvent) => void;
  withSearch?: boolean;
  listElementProps?: HTMLAttributes<HTMLDivElement>;
}

const EquipList: React.FC<IEquipListProps> = ({
  showEmptyMessage = false,
  criteria = {},
  header,
  onSelectEquipItem,
  withSearch = false,
  listElementProps = {},
}) => {
  const [isLoading, setIsLoading] = React.useState(true);
  const [err, setErr] = React.useState<Error>();
  const [data, setData] = React.useState<IEquip[]>([]);
  const [q, setQ] = React.useState('');

  const load = React.useCallback(async () => {
    try {
      setIsLoading(true);
      const res = await getEquipItems(criteria);
      setData(res);
    } catch (e) {
      setErr(e as Error);
    } finally {
      setIsLoading(false);
    }
  }, [criteria]);

  React.useEffect(() => {
    load();
  }, [load]);

  const filteredData = React.useMemo(() => {
    if (!withSearch || !q.length) return data;
    return data.filter((x) => x.name.toLocaleLowerCase().includes(q.toLowerCase()));
  }, [data, q, withSearch]);

  const subItemsMap = React.useMemo(() => {
    return filteredData.reduce<Record<number, IEquip[]>>((acc, eq) => {
      if (eq.id_parent) {
        if (!acc[eq.id_parent]) acc[eq.id_parent] = [];
        acc[eq.id_parent].push(eq);
      }
      return acc;
    }, {});
  }, [filteredData]);

  if (isLoading) return <PageLoader />;
  if (err) return <PohAlert variant={AlertVariant.Danger}>{err.message}</PohAlert>;

  const renderLevel = (items: IEquip[], level = 0) => {
    return (
      <PohList
        flush={level > 0}
        data={items.map((item) => {
          return {
            key: item.id,
            children: (
              <>
                <EquipListItem item={item} />
                {!!subItemsMap[item.id]?.length && (
                  <div
                    style={{ marginLeft: level * 8 }}
                    className={clsx(level > 0 && 'border-start')}
                  >
                    {renderLevel(subItemsMap[item.id], level + 1)}
                  </div>
                )}
              </>
            ),
            action: !!onSelectEquipItem,
            onClick: onSelectEquipItem
              ? (e) => {
                  e.stopPropagation();
                  onSelectEquipItem(item, e);
                }
              : undefined,
          };
        })}
      />
    );
  };

  return (
    <div>
      {data.length > 0 && header}
      {data.length > 0 && withSearch && (
        <>
          <PohInput type={InputTypes.search} value={q} onChange={setQ} placeholder="Найти" />
        </>
      )}
      {filteredData.length === 0 && showEmptyMessage && <Empty>Пока тут пусто...</Empty>}
      {filteredData.length > 0 && (
        <div {...listElementProps}>
          {renderLevel(filteredData.filter((x) => criteria.id_parent || !x.id_parent))}
        </div>
      )}
    </div>
  );
};

export default EquipList;
