import React from 'react';

import { showModal } from '@ui-kit/Modal';

import AddEquipModal from './AddEquipModal';
import { IEquip } from '../../../@types/equip.types';

export function addEquipModal(onAdd: (addedEquip: IEquip) => void) {
  showModal({
    title: 'Добавить снарягу',
    children: (closeHandler: () => void) => (
      <AddEquipModal
        onSave={(newItem) => {
          onAdd(newItem);
          closeHandler();
        }}
        onCancel={closeHandler}
      />
    ),
  });
}

export const addEquipModalAsync = (): Promise<IEquip> => {
  return new Promise((res) => {
    showModal({
      title: 'Добавить снарягу',
      children: (closeHandler: () => void) => (
        <AddEquipModal
          onSave={(newItem) => {
            res(newItem);
            closeHandler();
          }}
          onCancel={closeHandler}
        />
      ),
    });
  });
};

export default { addEquipModal };
