import Plus from '@pohodnik/icons/svg/Signs/Plus';

import { IGetEquipCriteria } from '@apps/Hiking/@services/equip.service';
import { IEquip } from '@apps/Hiking/@types/equip.types';
import { addEquipModalAsync } from '@apps/Hiking/equip/HikingEquip/addEquip/addEduipModal';
import PohButton from '@ui-kit/Button';
import { showModal } from '@ui-kit/Modal';

import EquipList from '../EquipList';

export const selectOneEquipItemInModal = (criteria?: IGetEquipCriteria): Promise<IEquip> => {
  return new Promise((res) => {
    showModal({
      title: 'Моё снаряжение',
      style: { minWidth: 400 },
      children: (clos) => (
        <>
          <EquipList
            criteria={criteria}
            withSearch
            listElementProps={{ style: { maxHeight: 480, overflowY: 'auto' } }}
            onSelectEquipItem={(r) => {
              res(r);
              clos();
            }}
          />
        </>
      ),
      footer: (clos: any) => (
        <>
          <PohButton
            block
            onClick={async (ev) => {
              const newItem = await addEquipModalAsync();
              ev.stopPropagation();
              res(newItem);
              clos();
            }}
          >
            <Plus /> Добавить новый элемент снаряжения
          </PohButton>
        </>
      ),
    });
  });
};
